// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0)); // caller is not the current owner (owner == address(0))
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            assertTrue(c.owner() == address(0), "non-owner must not change owner");
        } catch {
            assertTrue(c.owner() == address(0), "non-owner must not change owner");
        }
    }
}
